package dev.eugheist.tc4modern;

import com.mojang.blaze3d.vertex.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.RenderLevelStageEvent;

/** Original bell home/marker overlays and the flowing script ribbon (quality 16). */
@EventBusSubscriber(modid=TC4Modern.MODID,value=Dist.CLIENT)
public final class GolemBellClient {
 static final int[] COLORS={0xF0F0F0,15435844,12801229,6719955,14602026,4312372,14188952,0x434343,0xA0A0A0,2651799,8073150,2437522,5320730,3887386,11743532,0x1E1B1B};
 static long homes,marks,links;static double lastWave;static int lastQuality,lastSegments;
 static final net.minecraft.client.renderer.RenderType HOME=type("misc/home.png"),MARK=type("misc/mark.png"),EMPTY=type("blocks/empty.png"),SCRIPT=type("misc/script.png");
 static net.minecraft.client.renderer.RenderType type(String path){return NodeRenderTypes.additive(AlchemyContent.id("textures/"+path));}
 static int color(double time,int phase,int dye,float alpha){int rgb=dye>=0&&dye<16?COLORS[dye]:((int)((Math.sin(time/12+phase)*.2+.8)*255)<<16)|((int)((Math.sin(time/14+phase)*.2+.8)*255)<<8)|(int)((Math.sin(time/16+phase)*.2+.8)*255);return ((int)(255*alpha)<<24)|rgb;}
 static void vertex(VertexConsumer out,PoseStack pose,Vec3 p,float u,float v,int color){out.addVertex(pose.last(),(float)p.x,(float)p.y,(float)p.z).setUv(u,v).setColor(color);}
 static void face(VertexConsumer out,PoseStack pose,Vec3 center,Direction side,double size,int color){Vec3 normal=Vec3.atLowerCornerOf(side.getNormal());Vec3 u=side.getAxis()==Direction.Axis.Y?new Vec3(1,0,0):new Vec3(-normal.z,0,normal.x);Vec3 v=normal.cross(u);u=u.scale(size/2);v=v.scale(size/2);vertex(out,pose,center.subtract(u).subtract(v),0,1,color);vertex(out,pose,center.add(u).subtract(v),1,1,color);vertex(out,pose,center.add(u).add(v),1,0,color);vertex(out,pose,center.subtract(u).add(v),0,0,color);}
 static Vec3 point(Vec3 start,Vec3 end,Direction side,double dist,int i,int length,double time){double f=i/(double)length,envelope=1-Math.abs(i-length/2.0)/(length/2.0);double phase=side.ordinal()*20+dist*(1-f)*WarpClientConfig.golemLinkQuality()-time/5;Vec3 wobble=new Vec3(Math.sin((phase+end.z%16)/4),Math.sin((phase+end.x%16)/3),Math.sin((phase+end.y%16)/2)).scale(.5*envelope);double taper=Math.min(1,(length-i)/(WarpClientConfig.golemLinkQuality()/2.0));return start.add(end.add(Vec3.atLowerCornerOf(side.getNormal()).scale(.5*taper)).subtract(start).add(wobble).scale(f));}
 static void line(VertexConsumer out,PoseStack pose,Vec3 start,Vec3 end,Direction side,double time,int dye){double dist=start.distanceTo(end);int quality=WarpClientConfig.golemLinkQuality();if(quality<4)return;int length=Math.max(quality,(int)Math.round(dist)*quality);lastQuality=quality;lastSegments=length;for(int i=0;i<length;i++){Vec3 a=point(start,end,side,dist,i,length,time),b=point(start,end,side,dist,i+1,length,time);float ua=(float)((1-i/(double)length)*dist-time*.005),ub=(float)((1-(i+1)/(double)length)*dist-time*.005);int ca=color(time,side.ordinal()+i,dye,(float)(Math.min(.75,1.5*i/length)*Math.min(1,(length-i)/(WarpClientConfig.golemLinkQuality()/2.0)))),cb=color(time,side.ordinal()+i+1,dye,(float)(Math.min(.75,1.5*(i+1)/length)*Math.min(1,(length-i-1)/(WarpClientConfig.golemLinkQuality()/2.0))));vertex(out,pose,a.add(0,-.05,0),ua,1,ca);vertex(out,pose,a.add(0,.05,0),ua,0,ca);vertex(out,pose,b.add(0,.05,0),ub,0,cb);vertex(out,pose,b.add(0,-.05,0),ub,1,cb);lastWave=a.y;}links++;}
 static void markerChanged(int color){ClientKnowledge.notifications.add(net.minecraft.network.chat.Component.translatable("tc.markerchange").getString().replace("%n",GolemColors.NAMES[color]),System.nanoTime()/1_000_000L);}
 /** Bell.selected plus the client-side UUID fallback for entity ids renumbered by a reload. */
 static StrawGolem selected(net.minecraft.world.item.ItemStack stack,Minecraft mc){var g=Golemancy.Bell.selected(stack,mc.level);var t=NoteData.tag(stack);if(g!=null||!t.hasUUID("GolemUUID")||!t.getString("dimension").equals(mc.level.dimension().location().toString()))return g;var id=t.getUUID("GolemUUID");for(var e:mc.level.entitiesForRendering())if(e instanceof StrawGolem golem&&golem.getUUID().equals(id))return golem;return null;}
 @SubscribeEvent static void render(RenderLevelStageEvent event){if(event.getStage()!=RenderLevelStageEvent.Stage.AFTER_LEVEL)return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return;var stack=mc.player.getMainHandItem();boolean bell=stack.is(Golemancy.BELL.get());if(!bell&&!(stack.getItem() instanceof Golemancy.Placer))return;var tag=NoteData.tag(stack);var golem=bell?selected(stack,mc):null;if(bell&&golem==null)return;var pose=new PoseStack();pose.mulPose(event.getModelViewMatrix());var eye=event.getCamera().getPosition();pose.translate(-eye.x,-eye.y,-eye.z);var buffers=mc.renderBuffers().bufferSource();double time=(System.nanoTime()/30000000.0)%32767;
 if(bell&&tag.contains("homePos")){var home=BlockPos.of(tag.getLong("homePos"));var side=Direction.from3DDataValue(tag.getByte("homeFace"));var container=home.relative(side.getOpposite());if(mc.player.distanceToSqr(Vec3.atCenterOf(container))<4096){face(buffers.getBuffer(HOME),pose,Vec3.atCenterOf(container).add(Vec3.atLowerCornerOf(side.getNormal()).scale(.51)),side,.65,color(time,side.ordinal(),-1,1));homes++;}}
 for(var value:tag.getList("markers",10)){var marker=(net.minecraft.nbt.CompoundTag)value;var pos=BlockPos.of(marker.getLong("pos"));if(mc.player.distanceToSqr(Vec3.atCenterOf(pos))>=4096)continue;var side=Direction.from3DDataValue(marker.getByte("side"));int dye=marker.getByte("color"),rgb=color(time,side.ordinal(),dye,1);Vec3 center=Vec3.atCenterOf(pos).add(Vec3.atLowerCornerOf(side.getNormal()).scale(.51));face(buffers.getBuffer(MARK),pose,center,side,.4,rgb);marks++;var adjacent=pos.relative(side);if(mc.level.isEmptyBlock(adjacent))for(var direction:Direction.values())face(buffers.getBuffer(EMPTY),pose,Vec3.atCenterOf(adjacent).add(Vec3.atLowerCornerOf(direction.getNormal()).scale(.49)),direction,.98,rgb);if(golem!=null&&WarpClientConfig.golemLinkQuality()>=4){float partial=event.getPartialTick().getGameTimeDeltaPartialTick(false);Vec3 start=golem.getPosition(partial).add(0,golem.getBbHeight(),0);line(buffers.getBuffer(SCRIPT),pose,start,center,side,time,dye);}}
 buffers.endBatch(HOME);buffers.endBatch(MARK);buffers.endBatch(EMPTY);buffers.endBatch(SCRIPT);
 }
}
